window.MOTIF_CATALOG_CHUNKS[0]={"cards":[{"id":"MM-RULE-CARD","row_version":4,"title":"규칙_카드","original":"Card Guide","aliases":["카드 규칙","카드 사용법"],"kind":"rule","facet_id":null,"node_kind":null,"parent_id":null,"tag_path":[],"summary":"하얀용의 모티브 라이브러리의 카드 표기·설명·색상·연결 규칙이다.","accent":"#747C72","tab":"#747C72","facet":"이용 규칙","bookmark":"","entry_url":"cards/MM-RULE-CARD/index.html"},{"id":"MM-RULE-TAG","row_version":1,"title":"규칙_태그","original":"Tag Guide","aliases":["태그 규칙","분류 안내"],"kind":"rule","facet_id":null,"node_kind":null,"parent_id":null,"tag_path":[],"summary":"태그는 카드의 성격과 관계를 찾는 길이다. 모든 태그 키워드는 카드로 등록하고 각 싱글페이지에 뜻과 관련 카드를 기록한다.","accent":"#747C72","tab":"#747C72","facet":"이용 규칙","bookmark":"","entry_url":"cards/MM-RULE-TAG/index.html"},{"id":"MM-PERSON-WHTDRGON","row_version":1,"title":"하얀용","original":"WhtDrgon","aliases":["김동은","Kim Dong-eun"],"kind":"person","facet_id":null,"node_kind":null,"parent_id":null,"tag_path":[],"summary":"하얀용은 김동은이 사용하는 이름이다. 메제웍스 대표이자 세계관 IP 전략가로서 게임·콘텐츠 세계관과 팬덤 경험을 설계한다.","accent":"#607e70","tab":"#a1b5a6","facet":"라이브러리","bookmark":"인물","entry_url":"cards/MM-PERSON-WHTDRGON/index.html"},{"id":"MM-ORG-MEJE","row_version":2,"title":"메제","original":"MEJE Works","aliases":["메제웍스","MEJE","MEJE Works"],"kind":"organization","facet_id":null,"node_kind":null,"parent_id":null,"tag_path":[],"summary":"메제(메제웍스)는 세계관·캐릭터·콘텐츠 IP를 기획하고 팬덤 경험을 설계하는 스튜디오다. 김동은이 대표를 맡고 있다.","accent":"#6d7886","tab":"#aab9ca","facet":"라이브러리","bookmark":"조직","entry_url":"cards/MM-ORG-MEJE/index.html"},{"id":"ML-T00001","row_version":1,"title":"모티프","original":"Motif","aliases":["Motif","motif"],"kind":"keyword","facet_id":"ML-F01","node_kind":"group","parent_id":"ML-F01","tag_path":[],"summary":"이야기와 표현에서 반복되어 의미를 만드는 소재·행동·관계·이미지의 단위다. 서로 다른 작품에서 형태를 바꾸어 나타날 수 있다.","accent":"#5C7669","tab":"#9A6A55","facet":"개념 유형","bookmark":"모티프","entry_url":"cards/ML-T00001/index.html"},{"id":"ML-T00012","row_version":1,"title":"클리셰","original":"Cliché","aliases":["Cliché","Cliche","클리세"],"kind":"keyword","facet_id":"ML-F01","node_kind":"group","parent_id":"ML-F01","tag_path":[],"summary":"반복적으로 사용되어 수용자가 전개나 표현을 쉽게 예상하는 관습적 요소다. 상투성의 판단은 장르와 시기, 사용 맥락에 따라 달라진다.","accent":"#5C7669","tab":"#778F70","facet":"개념 유형","bookmark":"클리셰","entry_url":"cards/ML-T00012/index.html"},{"id":"ML-T00021","row_version":1,"title":"신화소","original":"Mytheme","aliases":["Mytheme"],"kind":"keyword","facet_id":"ML-F01","node_kind":"group","parent_id":"ML-F01","tag_path":[],"summary":"신화와 전승을 분석할 때 의미를 이루는 관계의 단위다. 기원·금기·희생·경계 같은 관계가 다른 이야기 속에서 어떻게 변형되는지 살핀다.","accent":"#5C7669","tab":"#8B739C","facet":"개념 유형","bookmark":"신화소","entry_url":"cards/ML-T00021/index.html"},{"id":"ML-T00030","row_version":1,"title":"레퍼토리","original":"Repertoire","aliases":["Repertoire","레파토리"],"kind":"keyword","facet_id":"ML-F01","node_kind":"group","parent_id":"ML-F01","tag_path":[],"summary":"특정 장르·작가·작품군 등에서 사용할 수 있는 표현과 이야기 장치의 묶음이다. 이 라이브러리에서는 관련 카드들을 함께 읽는 컬렉션으로도 구성한다.","accent":"#5C7669","tab":"#A58A4E","facet":"개념 유형","bookmark":"레퍼토리","entry_url":"cards/ML-T00030/index.html"},{"id":"ML-T00039","row_version":1,"title":"미장센","original":"Mise-en-scène","aliases":["Mise-en-scène","Mise en scene"],"kind":"keyword","facet_id":"ML-F01","node_kind":"group","parent_id":"ML-F01","tag_path":[],"summary":"공간·세트·소품·의상·조명과 인물의 배치·동선으로 장면의 의미를 구성하는 방식이다. 촬영 각도와 편집은 관련되지만 별도의 연출 요소로 구별한다.","accent":"#5C7669","tab":"#528982","facet":"개념 유형","bookmark":"미장센","entry_url":"cards/ML-T00039/index.html"},{"id":"ML-T00072","row_version":1,"title":"서구권 애니메이션","original":"Animation (Western)","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"서구권 제작 맥락의 애니메이션을 찾는 매체 분류다. TV·극장·단편 등 작품의 형식은 하위 태그로 구별한다.","accent":"#55758A","tab":"#8B739C","facet":"미디어","bookmark":"서구권 애니메이션","entry_url":"cards/ML-T00072/index.html"},{"id":"ML-T00049","row_version":1,"title":"일본 애니메이션","original":"Anime","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"일본 애니메이션 작품을 찾는 매체 분류다. TV·극장·OVA·ONA 등 공개 형식을 함께 구별할 수 있다.","accent":"#55758A","tab":"#A07A87","facet":"미디어","bookmark":"일본 애니메이션","entry_url":"cards/ML-T00049/index.html"},{"id":"ML-T00051","row_version":1,"title":"코믹북","original":"Comic Book","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"그림과 칸의 연속으로 이야기를 전하는 코믹북 매체 분류다. 단행본·연재물·그래픽 노블 등의 형식으로 나눈다.","accent":"#55758A","tab":"#A58A4E","facet":"미디어","bookmark":"코믹북","entry_url":"cards/ML-T00051/index.html"},{"id":"ML-T00106","row_version":1,"title":"팬픽","original":"Fan Fics","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"기존 작품이나 인물을 바탕으로 팬이 만든 서사 작품이다. 소설·대본 등 표현 형식과 원작과의 관계를 함께 구별한다.","accent":"#55758A","tab":"#9B8194","facet":"미디어","bookmark":"팬픽","entry_url":"cards/ML-T00106/index.html"},{"id":"ML-T02487","row_version":1,"title":"영화","original":"Film","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"연속된 영상을 일정한 러닝타임의 작품으로 구성하는 매체다. 실사와 애니메이션 모두를 포함한다.","accent":"#55758A","tab":"#688B82","facet":"미디어","bookmark":"영화","entry_url":"cards/ML-T02487/index.html"},{"id":"ML-T00058","row_version":2,"title":"애니메이션 영화","original":"Animated Films","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T02487","tag_path":[],"summary":"움직이는 그림이나 인형, 컴퓨터 그래픽 등의 제작 방식으로 장면을 구성한 영화. 제작 기법과 상영 형식은 다양하며 특정 연령이나 장르로 한정되지 않는다.","accent":"#55758A","tab":"#688B82","facet":"미디어","bookmark":"애니메이션 영화","entry_url":"cards/ML-T00058/index.html"},{"id":"ML-T02488","row_version":1,"title":"게임","original":"Game","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"규칙과 참여자의 행위로 진행되는 놀이와 작품의 매체 분류다. 비디오게임·테이블톱 게임 등과 중첩되는 탐색 경로를 가질 수 있다.","accent":"#55758A","tab":"#758A63","facet":"미디어","bookmark":"게임","entry_url":"cards/ML-T02488/index.html"},{"id":"ML-T00066","row_version":1,"title":"문학","original":"Literature","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"언어를 주요 표현 수단으로 삼는 작품의 매체 분류다. 소설·시·희곡·에세이·웹소설 등을 포함한다.","accent":"#55758A","tab":"#9B765F","facet":"미디어","bookmark":"문학","entry_url":"cards/ML-T00066/index.html"},{"id":"ML-T00164","row_version":1,"title":"웹소설","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T00066","tag_path":[],"summary":"웹을 주요 공개·연재 경로로 삼는 소설 형식이다. 작품의 장르와 연재·공개 방식은 별도의 태그로 구별한다.","accent":"#55758A","tab":"#9B765F","facet":"미디어","bookmark":"웹소설","entry_url":"cards/ML-T00164/index.html"},{"id":"ML-T00139","row_version":1,"title":"음악·음향","original":"Music And Sound Effects","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"노래·연주·앨범과 효과음 등 청각적 표현을 중심으로 한 매체 분류다. 작품 속 음악의 기능을 설명하는 소리·음악 태그와 구별한다.","accent":"#55758A","tab":"#947FA5","facet":"미디어","bookmark":"음악·음향","entry_url":"cards/ML-T00139/index.html"},{"id":"ML-T00142","row_version":2,"title":"앨범","original":"Album","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T00139","tag_path":[],"summary":"여러 음악 트랙을 하나의 제목과 구성으로 묶어 발표하는 음악 매체. 곡의 순서와 표지, 전체 주제가 모여 한 번의 듣기 경험을 만든다.","accent":"#55758A","tab":"#947FA5","facet":"미디어","bookmark":"앨범","entry_url":"cards/ML-T00142/index.html"},{"id":"ML-T02495","row_version":1,"title":"뉴미디어","original":"New Media","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"웹과 디지털 환경을 바탕으로 유통되거나 참여하는 콘텐츠를 찾는 매체 분류다. 웹영상·팟캐스트·SNS 서사 등 여러 형식을 포함한다.","accent":"#55758A","tab":"#71969D","facet":"미디어","bookmark":"뉴미디어","entry_url":"cards/ML-T02495/index.html"},{"id":"ML-T00194","row_version":2,"title":"대체 현실 게임","original":"Alternate Reality Game","aliases":["대체현실게임","Alternate Reality Game","ARG"],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T02495","tag_path":[],"summary":"현실의 웹페이지·영상·메시지·장소 등을 이야기의 단서처럼 사용해 참가자가 허구의 사건이 실제로 벌어지는 듯 추적하고 협력하게 하는 참여형 게임 형식. 이야기와 일상 매체의 경계를 놀이의 일부로 삼는다.","accent":"#55758A","tab":"#71969D","facet":"미디어","bookmark":"대체 현실 게임","entry_url":"cards/ML-T00194/index.html"},{"id":"ML-T02496","row_version":1,"title":"인쇄 매체","original":"Print Media","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"종이에 인쇄되어 전달되는 도서·신문·잡지·광고 등의 매체 분류다. 문학이나 만화처럼 내용 형식이 다른 분류와 함께 연결될 수 있다.","accent":"#55758A","tab":"#9E8F6C","facet":"미디어","bookmark":"인쇄 매체","entry_url":"cards/ML-T02496/index.html"},{"id":"ML-T00147","row_version":1,"title":"라디오·오디오","original":"Radio","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"소리를 중심으로 내용을 전하는 방송과 녹음 매체다. 라디오 드라마·오디오북 등 이야기와 음향의 결합을 포함한다.","accent":"#55758A","tab":"#7A879E","facet":"미디어","bookmark":"라디오·오디오","entry_url":"cards/ML-T00147/index.html"},{"id":"ML-T02501","row_version":1,"title":"연속그림","original":"Sequential Art","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"이어지는 그림과 장면의 관계로 이야기를 전하는 매체 분류다. 만화의 문화권·유통 형식 등과 별도의 탐색 관계를 가질 수 있다.","accent":"#55758A","tab":"#A68A62","facet":"미디어","bookmark":"연속그림","entry_url":"cards/ML-T02501/index.html"},{"id":"ML-T00084","row_version":1,"title":"테이블톱 게임","original":"Tabletop Games","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"탁상에서 규칙·말·카드·대화 등으로 진행하는 게임 매체다. 보드게임·카드게임·TRPG·미니어처 게임 등을 포함한다.","accent":"#55758A","tab":"#80906E","facet":"미디어","bookmark":"테이블톱 게임","entry_url":"cards/ML-T00084/index.html"},{"id":"ML-T00085","row_version":2,"title":"보드게임","original":"Board Games","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T00084","tag_path":[],"summary":"판과 말, 카드 같은 물리적 도구를 두고 규칙에 따라 함께 즐기는 게임. 작품 안에서는 등장인물의 사고방식이나 사회의 문화를 보여 주는 소품이 된다.","accent":"#55758A","tab":"#80906E","facet":"미디어","bookmark":"보드게임","entry_url":"cards/ML-T00085/index.html"},{"id":"ML-T00086","row_version":3,"title":"카드게임","original":"Card Games","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T00084","tag_path":[],"summary":"기호와 숫자 등이 적힌 카드의 조합으로 겨루거나 협력하는 게임. 손에 쥔 정보와 남에게 보이는 정보의 차이가 재미를 만든다. 카드를 화면에서 모으고 겨루도록 만들면 디지털 카드 대전 게임의 형식이 된다.","accent":"#55758A","tab":"#80906E","facet":"미디어","bookmark":"카드게임","entry_url":"cards/ML-T00086/index.html"},{"id":"ML-T00061","row_version":1,"title":"텔레비전","original":"Television","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"방송 편성이나 프로그램 형식을 중심으로 한 영상 매체 분류다. 드라마·예능·교양·뉴스 등 다양한 프로그램을 포함한다.","accent":"#55758A","tab":"#8C7B9E","facet":"미디어","bookmark":"텔레비전","entry_url":"cards/ML-T00061/index.html"},{"id":"ML-T00152","row_version":1,"title":"연극·무대공연","original":"Theater","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"배우나 연행자가 공간과 시간 안에서 수행하는 공연 매체다. 연극·뮤지컬·오페라·무용·인형극 등을 포함한다.","accent":"#55758A","tab":"#A17978","facet":"미디어","bookmark":"연극·무대공연","entry_url":"cards/ML-T00152/index.html"},{"id":"ML-T00076","row_version":1,"title":"비디오게임","original":"Videogame","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"전자 장치의 화면과 입력을 통해 규칙을 실행하는 게임 매체다. PC·콘솔·모바일 등의 플랫폼은 하위 태그로 구별한다.","accent":"#55758A","tab":"#648E8D","facet":"미디어","bookmark":"비디오게임","entry_url":"cards/ML-T00076/index.html"},{"id":"ML-T00090","row_version":1,"title":"웹코믹","original":"Webcomics","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"group","parent_id":"ML-F02","tag_path":[],"summary":"웹을 통해 공개되는 연속그림 작품의 매체 분류다. 세로 스크롤 웹툰뿐 아니라 웹 스트립과 웹 그래픽 노블도 포함한다.","accent":"#55758A","tab":"#AB805A","facet":"미디어","bookmark":"웹코믹","entry_url":"cards/ML-T00090/index.html"},{"id":"ML-T00091","row_version":1,"title":"웹툰","original":"Webtoon","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T00090","tag_path":[],"summary":"웹에서 감상하도록 구성된 만화 형식이다. 세로 스크롤을 활용하는 경우가 많으며, 화면과 연재 방식에 맞춘 장면의 연결이 특징적이다.","accent":"#55758A","tab":"#AB805A","facet":"미디어","bookmark":"웹툰","entry_url":"cards/ML-T00091/index.html"},{"id":"ML-T00116","row_version":4,"title":"미술","original":"Visual arts","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T02506","tag_path":[],"summary":"그림·조각·사진 등 시각적 형식으로 만든 작품과 그 제작·감상 맥락을 모으는 매체 분류. 기법과 소재, 예술가의 역할은 하위 카드에서 구별한다. 인물이 직접 그림을 만드는 미술 활동을 중심에 둔 한 회차도 이 매체를 이야기의 중심에 놓는다.","accent":"#55758A","tab":"#8B8C83","facet":"미디어","bookmark":"미술","entry_url":"cards/ML-T00116/index.html"},{"id":"ML-T00175","row_version":2,"title":"아시아 애니메이션","original":"Asian Animation","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T02506","tag_path":[],"summary":"아시아 여러 지역에서 제작·발표된 애니메이션을 찾는 매체 분류. 한 나라의 제작 양식을 아시아 전체의 공통 형식으로 묶지 않고 국가와 형식의 차이를 살핀다.","accent":"#55758A","tab":"#8B8C83","facet":"미디어","bookmark":"아시아 애니메이션","entry_url":"cards/ML-T00175/index.html"},{"id":"ML-T00105","row_version":2,"title":"팬 창작물","original":"Fan Works","aliases":["2차 창작물","팬워크"],"kind":"keyword","facet_id":"ML-F02","node_kind":"tag","parent_id":"ML-T02506","tag_path":[],"summary":"팬이 좋아하는 작품의 인물이나 세계를 바탕으로 만든 비공식 이야기, 그림, 영상 등 다양한 창작물이다.","accent":"#55758A","tab":"#8B8C83","facet":"미디어","bookmark":"팬 창작물","entry_url":"cards/ML-T00105/index.html"},{"id":"ML-T00207","row_version":2,"title":"모험","original":"Adventure","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"group","parent_id":"ML-F03","tag_path":[],"summary":"인물이 익숙한 자리에서 벗어나 낯선 장소와 위험, 과제를 만나는 이야기 유형. 발견과 이동, 선택의 연속이 중심이 되며 여러 장르와 결합할 수 있다. 모험에 유리하게 짜인 세계는 이런 여정이 거듭 일어날 수 있도록 마련된 배경이다.","accent":"#8A687E","tab":"#778F70","facet":"장르","bookmark":"모험","entry_url":"cards/ML-T00207/index.html"},{"id":"ML-T00215","row_version":3,"title":"판타지","original":"Fantasy","aliases":["Fantasy"],"kind":"keyword","facet_id":"ML-F03","node_kind":"group","parent_id":"ML-F03","tag_path":[],"summary":"마법과 초자연적 존재처럼 현실 법칙을 벗어나는 요소를 이야기의 핵심 조건으로 삼는 장르다. 공포·SF와 겹치는 경계도 있다. 북미 변경지의 풍경을 가져온 미국 변경지를 닮은 판타지은 이 장르의 지역적 변형이다.","accent":"#8A687E","tab":"#8B739C","facet":"장르","bookmark":"판타지","entry_url":"cards/ML-T00215/index.html"},{"id":"ML-T00221","row_version":2,"title":"다크 판타지","original":"Dark Fantasy","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00215","tag_path":[],"summary":"마법과 이계의 요소를 유지하면서 공포와 잔혹함, 도덕적 불확실성을 강하게 담는 판타지 장르. 낯선 세계의 경이와 삶의 위협이 함께 놓인다.","accent":"#8A687E","tab":"#8B739C","facet":"장르","bookmark":"다크 판타지","entry_url":"cards/ML-T00221/index.html"},{"id":"ML-T00228","row_version":2,"title":"동물 판타지","original":"Animal Fantasy","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00215","tag_path":[],"summary":"동물이 이야기의 중심 인물을 맡고 마법, 신화적 존재 또는 비현실적 세계의 모험이 전개되는 판타지 장르. 단순히 동물이 등장한다는 이유만으로 묶지 않고 세계의 환상 규칙과 동물의 서사 역할을 함께 본다.","accent":"#8A687E","tab":"#8B739C","facet":"장르","bookmark":"동물 판타지","entry_url":"cards/ML-T00228/index.html"},{"id":"ML-T00239","row_version":3,"title":"사이버펑크","original":"Cyberpunk","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00231","tag_path":[],"summary":"발달한 정보 기술과 몸의 개조가 권력 집중과 사회적 불평등 속에서 작동하는 미래 장르다. 기술의 가능성과 그것을 소유한 세력의 통제가 함께 그려진다. 장르 전체의 사회 구조를 따르지 않고 외형만 가져오는 방식은 사이버펑크 분위기만 빌려 쓰기다.","accent":"#8A687E","tab":"#A58A4E","facet":"장르","bookmark":"사이버펑크","entry_url":"cards/ML-T00239/index.html"},{"id":"ML-T00260","row_version":2,"title":"민속 공포","original":"Folk Horror","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00248","tag_path":[],"summary":"지역 전승과 구전 신앙, 오래된 의례와 공동체의 금기에서 공포를 끌어오는 장르. 외딴 마을과 낯선 방문자는 가능한 구성 중 하나다.","accent":"#8A687E","tab":"#528982","facet":"장르","bookmark":"민속 공포","entry_url":"cards/ML-T00260/index.html"},{"id":"ML-T00318","row_version":2,"title":"가족 드라마","original":"Family Drama","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00317","tag_path":[],"summary":"가족 구성원 사이의 관계와 갈등을 중심에 놓고 일상, 책임, 화해와 변화를 다루는 이야기 장르다.","accent":"#8A687E","tab":"#9B8A6F","facet":"장르","bookmark":"가족 드라마","entry_url":"cards/ML-T00318/index.html"},{"id":"ML-T00338","row_version":2,"title":"대체역사","original":"Alternate History","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00330","tag_path":[],"summary":"실제 역사의 특정 분기점 이후 다른 사건이 이어졌다고 가정해 변화한 사회와 세계를 그리는 장르·설정. 바뀐 원인과 그 결과의 연결이 세계의 설득력을 만든다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"대체역사","entry_url":"cards/ML-T00338/index.html"},{"id":"ML-T00435","row_version":2,"title":"액션 RPG","original":"Action RPG","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00434","tag_path":[],"summary":"역할 수행 게임의 성장·장비·탐험 구조와 실시간 직접 조작 전투를 결합한 게임 장르. 수치에 따른 성장이 중요하면서도 공격과 회피의 순간 판단이 결과를 바꾼다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/ML-T00435/index.html"},{"id":"ML-T00493","row_version":2,"title":"연애 시뮬레이션","original":"Dating Sim","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00485","tag_path":[],"summary":"이용자가 일정과 선택, 능력치를 관리하며 인물과 관계를 쌓고 여러 결말에 도달하는 게임 장르다. 선택한 상대의 이야기를 알아가는 과정이 중심이 된다.","accent":"#8A687E","tab":"#7D8FA3","facet":"장르","bookmark":"연애 시뮬레이션","entry_url":"cards/ML-T00493/index.html"},{"id":"ML-T00502","row_version":2,"title":"얼터너티브 록","original":"Alternative Rock","aliases":["얼터너티브록"],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00494","tag_path":[],"summary":"기존 주류 록의 음색과 제작 관습에서 벗어난 여러 흐름을 묶어 부르는 음악 범주. 시대와 지역에 따라 가리키는 소리의 범위가 달라 단일한 연주 공식으로 정의하기 어렵다.","accent":"#8A687E","tab":"#A07A87","facet":"장르","bookmark":"얼터너티브 록","entry_url":"cards/ML-T00502/index.html"},{"id":"ML-T00507","row_version":3,"title":"데스메탈","original":"Death Metal","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00504","tag_path":[],"summary":"거친 보컬과 빠르고 강도 높은 연주를 특징으로 하는 익스트림 메탈의 한 갈래. 음악 장르와 작품 속 음향 이미지를 분류하는 키워드이다. 데스메탈의 특징에 메탈코어 구성을 결합한 장르가 데스코어이다.","accent":"#8A687E","tab":"#79866C","facet":"장르","bookmark":"데스메탈","entry_url":"cards/ML-T00507/index.html"},{"id":"ML-T00515","row_version":2,"title":"얼터너티브 힙합","original":"Alternative Hip Hop","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00511","tag_path":[],"summary":"힙합의 리듬과 랩을 바탕으로 록·재즈·전자음악 등 여러 형식과 비주류 주제를 결합하는 음악 흐름. 하나의 소리로 고정하기보다 관습을 벗어난 실험을 가리킨다.","accent":"#8A687E","tab":"#AF8665","facet":"장르","bookmark":"얼터너티브 힙합","entry_url":"cards/ML-T00515/index.html"},{"id":"ML-T00516","row_version":2,"title":"컨템퍼러리 R&B","original":"Contemporary R&B","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00511","tag_path":[],"summary":"소울과 펑크의 보컬·리듬을 바탕으로 팝, 힙합, 전자음악의 제작 방식을 섞어 발전한 현대 R&B 계열의 음악. 시대와 지역에 따라 사운드가 달라지는 넓은 장르다.","accent":"#8A687E","tab":"#AF8665","facet":"장르","bookmark":"컨템퍼러리 R&B","entry_url":"cards/ML-T00516/index.html"},{"id":"ML-T00519","row_version":4,"title":"펑크 음악","original":"Funk","aliases":["Funk"],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00511","tag_path":[],"summary":"강한 리듬과 반복되는 그루브를 중심에 두고 소울·리듬 앤드 블루스·재즈의 흐름에서 발전한 음악 장르다. 이 장르의 강한 리듬을 헤비메탈과 결합한 파생 장르는 펑크 메탈이다. 록의 악기 편성과 만난 파생 장르는 펑크록이다.","accent":"#8A687E","tab":"#AF8665","facet":"장르","bookmark":"펑크 음악","entry_url":"cards/ML-T00519/index.html"},{"id":"ML-T00524","row_version":2,"title":"드럼 앤 베이스","original":"Drum and Bass","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00520","tag_path":[],"summary":"빠른 브레이크비트와 두드러진 저음을 중심으로 전개되는 전자음악 장르. 드럼 리듬의 변화와 베이스가 곡의 추진력을 만든다.","accent":"#8A687E","tab":"#6D7BA1","facet":"장르","bookmark":"드럼 앤 베이스","entry_url":"cards/ML-T00524/index.html"},{"id":"ML-T00525","row_version":2,"title":"덥스텝","original":"Dubstep","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00520","tag_path":[],"summary":"영국에서 발전한 전자음악 장르로, 저음의 리듬과 공간감 있는 소리를 중심으로 여러 양식으로 확장되었다.","accent":"#8A687E","tab":"#6D7BA1","facet":"장르","bookmark":"덥스텝","entry_url":"cards/ML-T00525/index.html"},{"id":"ML-T00526","row_version":2,"title":"앰비언트","original":"Ambient","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00520","tag_path":[],"summary":"선율과 박자의 전면적 전개보다 음색·지속음·공간감을 통해 분위기를 만드는 음악 장르. 감상곡이나 장면의 배경음으로 쓰이며 조용함만을 뜻하지는 않는다.","accent":"#8A687E","tab":"#6D7BA1","facet":"장르","bookmark":"앰비언트","entry_url":"cards/ML-T00526/index.html"},{"id":"ML-T00533","row_version":2,"title":"포크","original":"Folk Music","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00527","tag_path":[],"summary":"악보나 음반의 한 판본보다 사람들의 반복된 연주와 구전 속에서 전승되고 변형되는 음악 전통이다. 현대의 창작자도 이 전통을 이어 새로운 노래를 만들 수 있다.","accent":"#8A687E","tab":"#9B8A6F","facet":"장르","bookmark":"포크","entry_url":"cards/ML-T00533/index.html"},{"id":"ML-T00534","row_version":2,"title":"컨트리","original":"Country Music","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00527","tag_path":[],"summary":"미국 민속음악 전통을 바탕으로 현악기 중심의 소리와 이야기를 들려주는 가사를 발전시킨 음악 장르. 시대에 따라 팝과 록 등과 결합하며 범위가 넓어졌다.","accent":"#8A687E","tab":"#9B8A6F","facet":"장르","bookmark":"컨트리","entry_url":"cards/ML-T00534/index.html"},{"id":"ML-T00539","row_version":4,"title":"클래식 음악","original":"Classical Music","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"서양의 오래된 공연·작곡 전통을 중심으로 묶어 부르는 음악 영역. 작품에서는 연주와 감상의 공간이 인물의 취향이나 시대 분위기를 나타낸다. 클래식 감상을 허세나 지루함으로 처리하는 묘사는 클래식 음악을 지루하게 묘사하기의 관습이다. 음악을 직접 들으며 선입견이 깨지는 이야기는 클래식 음악의 매력 재발견으로 이어진다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"클래식 음악","entry_url":"cards/ML-T00539/index.html"},{"id":"ML-T00561","row_version":2,"title":"초단편","original":"Flash Fiction","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"한 문장부터 몇 쪽에 이르는 매우 짧은 분량 안에 인물과 사건, 인상을 압축해 담는 소설 형식이다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"초단편","entry_url":"cards/ML-T00561/index.html"},{"id":"ML-T00588","row_version":3,"title":"다큐멘터리","original":"Documentary","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"현실의 사람과 사건, 현상을 자료와 촬영으로 탐구하는 비허구 영상 형식이다. 취재와 편집의 관점이 설명의 방향을 만든다. 연속극이 다큐멘터리의 제작 관습을 한 회에 빌려오면 다큐멘터리 형식의 특별 회차이 된다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"다큐멘터리","entry_url":"cards/ML-T00588/index.html"},{"id":"ML-T00829","row_version":2,"title":"신앙의 위기","original":"Crisis of Faith","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":"tag","parent_id":"ML-T00824","tag_path":[],"summary":"종교적 믿음을 지녔던 인물이 고통이나 의문 앞에서 믿음을 잃거나 다시 묻는다. 답을 찾는 과정이 정체성과 관계의 변화를 이끈다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"신앙의 위기","entry_url":"cards/ML-T00829/index.html"},{"id":"ML-T00839","row_version":2,"title":"계급 갈등","original":"Class Struggle","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":"tag","parent_id":"ML-T00838","tag_path":[],"summary":"서로 다른 사회 계층이 자원과 권리, 지배 질서를 두고 부딪친다. 개인 사이의 다툼 뒤에 구조적인 이해관계가 놓인다.","accent":"#936E72","tab":"#8B739C","facet":"갈등·장애","bookmark":"계급 갈등","entry_url":"cards/ML-T00839/index.html"},{"id":"ML-T00844","row_version":3,"title":"문화 규범 충돌","original":"Culture Clash","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":"tag","parent_id":"ML-T00838","tag_path":[],"summary":"서로 다른 문화의 인물이 같은 행동을 다르게 이해해 갈등이나 오해를 겪는다. 낯선 관습의 의미를 알아가는 과정이 관계와 세계관을 드러낸다. 낯선 집단의 말을 중재하는 언어에 능한 통역 담당자는 문화의 차이를 이해하는 통로가 된다.","accent":"#936E72","tab":"#8B739C","facet":"갈등·장애","bookmark":"문화 규범 충돌","entry_url":"cards/ML-T00844/index.html"},{"id":"ML-T00890","row_version":3,"title":"원형적 역할","original":"Archetypal Character","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"group","parent_id":"ML-F09","tag_path":[],"summary":"문화와 작품을 가로질러 알아볼 수 있는 역할과 성격의 뼈대를 지닌 인물 유형. 완성된 한 사람보다 여러 변주가 공유하는 형태를 설명한다. 인물에 한정되지 않은 반복 형식은 반복 변주되는 이야기 원형에서 다룬다.","accent":"#7B7594","tab":"#778F70","facet":"인물","bookmark":"원형적 역할","entry_url":"cards/ML-T00890/index.html"},{"id":"ML-T00891","row_version":1,"title":"선택받은 자","original":"The Chosen One","aliases":["Chosen One","The Chosen One"],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00890","tag_path":[],"summary":"예언·혈통·신적 선택 등으로 특별한 역할을 맡도록 지목된 인물이다. 선택의 근거와 인물이 그 역할을 받아들이는 방식이 갈등을 만든다.","accent":"#7B7594","tab":"#778F70","facet":"인물","bookmark":"선택받은 자","entry_url":"cards/ML-T00891/index.html"},{"id":"ML-T00901","row_version":3,"title":"반영웅","original":"Anti-Hero","aliases":["Antihero","안티히어로"],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00899","tag_path":[],"summary":"용기나 도덕적 완전함 같은 익숙한 영웅의 미덕을 충분히 갖추지 못해도 이야기의 중심에서 선한 결과를 이루는 인물. 결함과 영웅적 행동이 함께 존재한다. 변형된 후임자와 집단의 예로 원래 영웅보다 거친 후임자와 결함 있는 영웅들로 구성된 팀이 있다.","accent":"#7B7594","tab":"#8B739C","facet":"인물","bookmark":"반영웅","entry_url":"cards/ML-T00901/index.html"},{"id":"ML-T00926","row_version":3,"title":"예술가","original":"Artists","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00916","tag_path":[],"summary":"그림·조각·사진 등 시각 작품을 만들고 표현 방식을 발전시키는 인물 유형. 작품 속 역할을 볼 때 직업 명칭뿐 아니라 창작 활동과 다른 인물과의 관계를 함께 살핀다. 예술가라서 매력적이라고 여겨지는 인물은 직업 이미지가 관계 판단에 영향을 주는 변형이다.","accent":"#7B7594","tab":"#528982","facet":"인물","bookmark":"예술가","entry_url":"cards/ML-T00926/index.html"},{"id":"ML-T00951","row_version":1,"title":"출생의 비밀","original":"Secret Birth","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"출생과 혈연에 관한 정보가 감춰져 인물의 정체성이나 관계에 영향을 주는 장치다. 비밀의 공개가 기존의 소속과 권력 관계를 바꿀 수 있다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"출생의 비밀","entry_url":"cards/ML-T00951/index.html"},{"id":"ML-T00975","row_version":2,"title":"입양 가족","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"혈연 외의 관계를 통해 부모와 자녀가 되어 함께 살아가는 가족 구성을 찾는 태그다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"입양 가족","entry_url":"cards/ML-T00975/index.html"},{"id":"ML-T00978","row_version":2,"title":"선택한 가족","original":"Family of Choice","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"혈연이나 법적 관계 밖의 사람들이 서로를 돌보고 책임지며 가족과 같은 유대를 만드는 관계 설정이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"선택한 가족","entry_url":"cards/ML-T00978/index.html"},{"id":"ML-T00980","row_version":2,"title":"첫사랑","original":"First Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"인물이 처음 깊이 마음을 준 사람을 시간이 지난 뒤에도 특별하게 기억하고 새 관계와 비교하는 감정적 경험이다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"첫사랑","entry_url":"cards/ML-T00980/index.html"},{"id":"ML-T00984","row_version":2,"title":"금지된 사랑","original":"Forbidden Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"사회 규범이나 집단의 금기가 두 사람의 연애를 가로막아 관계를 숨기거나 공개적으로 이어 가기 어렵게 만든다. 편견에서 비롯한 금지와 동의·권력 차이 때문에 필요한 보호 목적의 제한은 구분해 다룬다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"금지된 사랑","entry_url":"cards/ML-T00984/index.html"},{"id":"ML-T00989","row_version":1,"title":"계약 결혼 관계","original":"","aliases":["계약결혼","계약 결혼"],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"감정 외의 목적이나 조건을 정한 합의로 맺는 혼인 관계다. 합의의 조건과 실제 관계의 변화 사이에서 이야기가 전개된다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"계약 결혼 관계","entry_url":"cards/ML-T00989/index.html"},{"id":"ML-T00996","row_version":2,"title":"우정·동료","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"서로를 친구나 동료로 받아들이고 신뢰를 쌓는 관계를 찾는 태그다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"우정·동료","entry_url":"cards/ML-T00996/index.html"},{"id":"ML-T01020","row_version":3,"title":"숙적","original":"Arch-Enemy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"여러 적 가운데 주인공과 가장 깊은 원한이나 대조를 이루는 상대. 단순히 강한 적이 아니라 반복된 대결이 서로의 정체성을 규정한다. 가족인 적이 반복해서 나타나는 아버지가 가장 큰 적이 되기는 한 변형이다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"숙적","entry_url":"cards/ML-T01020/index.html"},{"id":"ML-T01038","row_version":3,"title":"다섯 명의 팀","original":"Five-Man Band","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01034","tag_path":[],"summary":"중심 인물과 그를 보완하는 서로 다른 역할의 동료들로 이루어진 다섯 명 안팎의 모험 집단이다. 역할이 나뉜 팀의 친밀함은 구성원 모두가 참여하는 팀원들이 함께 연주하는 공연으로도 표현된다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"다섯 명의 팀","entry_url":"cards/ML-T01038/index.html"},{"id":"ML-T01090","row_version":2,"title":"확증 편향","original":"Confirmation Bias","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":"tag","parent_id":"ML-T01085","tag_path":[],"summary":"기존 믿음에 맞는 근거를 더 쉽게 찾고 신뢰하면서 반대 정보는 낮게 평가하거나 유리하게 해석하는 판단 경향. 인물의 오해나 집단 갈등이 고착되는 이유로 쓰일 수 있다.","accent":"#8E796B","tab":"#A07A87","facet":"동기·심리","bookmark":"확증 편향","entry_url":"cards/ML-T01090/index.html"},{"id":"ML-T01108","row_version":2,"title":"동물·식물·균류 계열","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"group","parent_id":"ML-F12","tag_path":[],"summary":"동물·식물·균류의 모습과 생태를 이야기 속 존재로 사용할 때 현실 참고와 허구적 변형을 찾는 분류다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"동물·식물·균류 계열","entry_url":"cards/ML-T01108/index.html"},{"id":"ML-T01109","row_version":2,"title":"현실 동물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01108","tag_path":[],"summary":"현실에 알려진 동물의 종과 생태적 특징을 이야기 속 존재의 출발점으로 삼는 분류다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"현실 동물","entry_url":"cards/ML-T01109/index.html"},{"id":"ML-T01110","row_version":2,"title":"말하는 동물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01108","tag_path":[],"summary":"동물 인물이 사람이나 다른 존재와 알아들을 수 있는 언어로 대화하는 설정을 찾는 분류다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"말하는 동물","entry_url":"cards/ML-T01110/index.html"},{"id":"ML-T01111","row_version":2,"title":"의인화 동물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01108","tag_path":[],"summary":"동물의 외형이나 생태적 특징을 지니면서 인간처럼 말하고 판단하거나 사회적 역할을 수행하는 존재를 찾는 분류다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"의인화 동물","entry_url":"cards/ML-T01111/index.html"},{"id":"ML-T01143","row_version":3,"title":"사이보그","original":"Cyborg","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"살아 있는 몸에 기계 부품과 제어 장치가 결합해 두 체계가 함께 움직이는 존재다. 몸의 경계와 정체성, 능력의 변화가 서사의 소재가 된다. 기계화된 몸을 항해에 특별히 활용하는 인물은 기계화된 우주선 조종사로 구체화된다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"사이보그","entry_url":"cards/ML-T01143/index.html"},{"id":"ML-T01152","row_version":2,"title":"우주적 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"하나의 행성이나 문명을 넘어 우주 규모에서 행동하거나 위협으로 인식되는 존재를 찾는 분류다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"우주적 존재","entry_url":"cards/ML-T01152/index.html"},{"id":"ML-T01174","row_version":1,"title":"숨겨진 초자연 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"일상 사회와 초자연적 질서가 함께 존재하지만 그 실재가 널리 알려지지 않은 세계다. 은폐의 방법과 두 사회의 접점이 설정의 핵심이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"숨겨진 초자연 세계","entry_url":"cards/ML-T01174/index.html"},{"id":"ML-T01181","row_version":1,"title":"평행세계","original":"Parallel World","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"서로 다른 상태나 역사를 가진 세계들이 나란히 존재하는 설정이다. 세계 간의 이동 가능성과 분기 원인이 작품마다 달라진다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"평행세계","entry_url":"cards/ML-T01181/index.html"},{"id":"ML-T01182","row_version":1,"title":"다중우주","original":"Multiverse","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"여러 우주가 함께 존재하는 세계 구조다. 우주 사이의 법칙·경계·접촉 가능성이 각각의 설정을 구별한다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"다중우주","entry_url":"cards/ML-T01182/index.html"},{"id":"ML-T01184","row_version":3,"title":"포켓 차원","original":"Pocket Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"현재 세계에 붙어 있으면서 보통 공간보다 더 넓은 내부나 숨겨진 장소를 제공하는 작은 별도 공간. 보관, 피신, 비밀 거주지처럼 쓰인다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/ML-T01184/index.html"},{"id":"ML-T01191","row_version":1,"title":"시간 회귀","original":"Time Regression","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"인물이나 세계의 시간이 이전 시점으로 돌아가는 설정이다. 과거의 기억이 남는지와 이후의 역사가 달라질 수 있는지가 중요한 구분점이다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 회귀","entry_url":"cards/ML-T01191/index.html"},{"id":"ML-T01192","row_version":1,"title":"시간 반복","original":"Time Loop","aliases":["타임 루프","Time Loop"],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"일정한 시간 구간이 되풀이되는 세계의 규칙이다. 반복되는 구간, 기억을 유지하는 존재와 반복을 끝내는 조건에 따라 다른 이야기를 만든다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 반복","entry_url":"cards/ML-T01192/index.html"},{"id":"ML-T01198","row_version":1,"title":"자기실현적 예언","original":"Self-Fulfilling Prophecy","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"예언을 알게 된 존재의 행동이 예언된 결과를 일으키는 인과 구조다. 예언을 피하려는 시도가 오히려 실현의 원인이 되는 변형을 포함한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"자기실현적 예언","entry_url":"cards/ML-T01198/index.html"},{"id":"ML-T01210","row_version":2,"title":"마법의 보편화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"마법을 사용할 기회가 소수의 혈통이나 신분에만 묶이지 않고 사회 전반으로 넓어지는 세계의 규칙을 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"마법의 보편화","entry_url":"cards/ML-T01210/index.html"},{"id":"ML-T01211","row_version":2,"title":"마법의 희소성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"마법을 쓸 수 있는 사람이나 마력의 공급이 제한되어 마법이 드문 자원처럼 다뤄지는 세계를 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"마법의 희소성","entry_url":"cards/ML-T01211/index.html"},{"id":"ML-T01214","row_version":2,"title":"기술과 마법의 공존","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"기술 장치와 마법이 같은 세계에서 어떤 관계를 맺으며 함께 쓰이는지 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"기술과 마법의 공존","entry_url":"cards/ML-T01214/index.html"},{"id":"ML-T01318","row_version":2,"title":"우주선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"tag","parent_id":"ML-T01313","tag_path":[],"summary":"우주선을 인물이 머무르고 이동하는 장소로 볼 때 선내 생활·항로·격리된 환경을 찾는 분류다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"우주선","entry_url":"cards/ML-T01318/index.html"},{"id":"ML-T01320","row_version":2,"title":"외계 행성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"tag","parent_id":"ML-T01313","tag_path":[],"summary":"지구 밖의 행성을 이야기의 주요 장소로 삼을 때 그 환경·거주 조건·사회 흔적을 찾는 분류다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/ML-T01320/index.html"},{"id":"ML-T01330","row_version":2,"title":"정치·통치","original":"Politics","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"세계 안에서 권한을 나누고 공동의 결정을 내리는 정치 조직과 통치 방식을 찾는 분류다. 국가의 이름이나 선악 평가와 통치 구조를 구별해 살핀다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"정치·통치","entry_url":"cards/ML-T01330/index.html"},{"id":"ML-T01331","row_version":2,"title":"군주제 사회","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"왕·여왕·황제 등 군주 지위가 국가 권한의 중심에 놓이는 사회와 그 권력 승계·궁정·신하 관계를 묶는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"군주제 사회","entry_url":"cards/ML-T01331/index.html"},{"id":"ML-T01332","row_version":2,"title":"공화제 사회","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"선출·대표·회의 등 군주 개인 밖의 공적 절차가 통치 정당성을 구성하는 사회를 묶는다. 제도의 이름과 실제 권력 운용은 별도로 살핀다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"공화제 사회","entry_url":"cards/ML-T01332/index.html"},{"id":"ML-T01333","row_version":2,"title":"제국 체제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"여러 지역이나 공동체를 하나의 중심 권력 아래 묶어 다스리는 제국의 구조와 그 확대·유지·쇠퇴를 찾는 분류다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"제국 체제","entry_url":"cards/ML-T01333/index.html"},{"id":"ML-T01334","row_version":2,"title":"도시국가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"도시와 가까운 배후 지역이 독자적인 정치 권한을 갖는 국가 형태를 묶는다. 작은 영토와 큰 외교·상업 영향력이 함께 나타날 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"도시국가","entry_url":"cards/ML-T01334/index.html"},{"id":"ML-T01335","row_version":2,"title":"부족 연합","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01330","tag_path":[],"summary":"독립성을 지닌 여러 지역 공동체가 공동 방위·의례·교역 또는 회의를 위해 연합하는 정치 형태를 묶는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"부족 연합","entry_url":"cards/ML-T01335/index.html"}]}.cards;